/* Barotico prototype — main script. English is the master language; FR and ES translations. */
const LANGS=["en","fr","es"];
const LANG_NAMES={en:"English",fr:"Français",es:"Español"};
/* Two choices only: English (original) and the browser's language. FR and ES are translated here; any other browser language is left to the browser's own translator. */
let lang="en", autoLang=false, browserLang="en", useBrowser=false;
function store(k,v){try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v)}catch(e){return null}}
function langName(l){try{const n=new Intl.DisplayNames([l],{type:"language"}).of(l);return n.charAt(0).toLocaleUpperCase(l)+n.slice(1)}catch(e){return LANG_NAMES[l]||l}}
(function detect(){
  const nav=(navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||"en"]).map(l=>String(l).slice(0,2).toLowerCase());
  browserLang=nav[0]||"en";
  const saved=store("barotico-lang");
  if(saved==="en"){lang="en";return}
  if(saved==="fr"||saved==="es"){lang=saved;useBrowser=true;return}
  if(saved==="browser"){useBrowser=browserLang!=="en";lang=LANGS.includes(browserLang)?browserLang:"en";return}
  if(browserLang!=="en"){useBrowser=true;autoLang=true;lang=LANGS.includes(browserLang)?browserLang:"en"}
})();
/* Path mode (barotico.com): real URLs /<lang>/<country-slug>/ generated by tools/prerender.js. The artifact preview keeps #hash routing. */
const PATHMODE=!!window.BAROTICO_PATH;
const PAGE_SLUG={comparer:"compare",medias:"media",apropos:"about",legal:"legal"};
const slugify=x=>String(x).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
function pathLangNow(){const m=location.pathname.match(/^\/(en|fr|es)(\/|$)/);return m?m[1]:"en"}
if(PATHMODE){const um=location.pathname.match(/^\/([a-z]{2})(\/.*)?$/);if(um&&!LANGS.includes(um[1]))location.replace("/en"+(um[2]||"/")+location.hash);}
if(PATHMODE){const pl=pathLangNow(),sv=store("barotico-lang");
  const want=(sv==="fr"||sv==="es")?sv:(!sv&&LANGS.includes(browserLang)&&browserLang!=="en")?browserLang:null;
  if(pl==="en"&&want&&sv!=="en"&&!/[?&]nolang/.test(location.search)){if(!sv)try{sessionStorage.setItem("barotico-auto","1")}catch(e){}location.replace("/"+want+location.pathname.replace(/^\/en(?=\/|$)/,"")+location.hash)}
  lang=pl;useBrowser=lang!=="en";autoLang=false;
  try{if(sessionStorage.getItem("barotico-auto")==="1"&&lang!=="en"){autoLang=true;sessionStorage.removeItem("barotico-auto")}}catch(e){}
  if(lang==="en"&&!LANGS.includes(browserLang)&&browserLang!=="en"&&!sv){autoLang=true;useBrowser=true}}
const tr=x=>x==null?"":typeof x==="string"?x:(x[lang]??x.en);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
function num(s){s=String(s);if(lang==="en")return s.replace(/(\d),(\d)/g,"$1.$2").replace(/(\d) (\d{3})/g,"$1,$2").replace(/ %/g,"%");if(lang==="es")return s.replace(/(\d) (\d{3})/g,"$1.$2");return s}

