function legalPage(){
  return `<div class="chead" style="grid-template-columns:minmax(0,1fr)"><div><p class="eyebrow">Barotico</p><h1>${tr(LEG.nav)}</h1><p class="lead" style="margin-top:10px">${tr(LEG.lead)}</p>
   <p class="mjump">${LEG.sections.map(([id,h])=>`<a href="#legal-${id}">${esc(tr(h))}</a>`).join("")}</p></div></div>
   <aside class="disc compact"><p>${tr(LEG.proto)}</p></aside>
   ${LEG.sections.map(([id,h,ps])=>`<section id="${id}" class="legal"><h2>${esc(tr(h))}</h2>${ps.map(p=>`<p>${esc(tr(p))}</p>`).join("")}</section>`).join("")}`;
}

