function govWeather(c){
  const g=c.gauges&&c.gauges[7];if(!g)return "";
  let v=parseFloat(String(g[1]).replace(",",".").replace(/[^\d.]/g,""));if(isNaN(v))return "";
  if(!/%/.test(String(g[1]))&&v<=10)v*=10; // ratings out of 10
  const i=v<25?0:v<40?1:v<55?2:3,[h,p]=t("weather")[i],ic=["M6 15a4 4 0 0 1 .5-8 5 5 0 0 1 9.5 1.5A3.5 3.5 0 0 1 16 15H6M9 17l-2 4M13 17l-2 4","M6 16a4 4 0 0 1 .5-8 5 5 0 0 1 9.5 1.5A3.5 3.5 0 0 1 16 16H6","M8 6a4 4 0 1 0 0 8M10 2v2M3 9H1M4 4 3 3M14 12a3 3 0 0 1 .5-6 4 4 0 0 1 7.5 1.5A2.5 2.5 0 0 1 22 12h-8","M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10zM12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2"][i];
  return `<div class="weather w${i}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ic}"/></svg><div><p class="eyebrow">${t("weather_h")}</p><b>${h}</b><p>${p}</p><p class="sources">${t("weather_note")}</p></div></div>`;
}
function dailyGap(){
  const pool=[];for(const k in PARTIES){if(!C[k])continue;for(const p of PARTIES[k]){const vv=verdictOf(k,p).v;if(vv)pool.push([k,p,vv])}}
  if(!pool.length)return "";
  const [k,p,vv]=pool[Math.floor(Math.random()*pool.length)];
  const facts=readyKeys().map(x=>[x,info(x)]).filter(([x,c])=>c&&c.fun).sort(()=>Math.random()-.5).slice(0,3);
  return `<section class="daily"><div class="dgap"><p class="eyebrow">${t("daily_h")} · ${esc(tr(C[k].name))}</p><blockquote>${(()=>{const ps=tr(vv).split(/\n\n+/);return ps.length>1?`<b>${esc(p.name)}</b> · ${esc(ps[1])}`:esc(ps[0])})()}</blockquote><a href="#${k}-${p.id}">${t("daily_more")} →</a></div>
   ${facts.length?`<div class="dfacts"><p class="eyebrow">${t("meanwhile")}</p>${facts.map(([x,c])=>`<a class="dfact" href="#${x}"><span class="mono">${esc(tr(c.name))}</span><span>${tr(c.fun)}</span></a>`).join("")}</div>`:""}</section>`;
}

