Object.assign(T.fr,{"f_lead":"Direction","f_seats":"Sièges","f_born":"Fondé en","f_gov":"Au pouvoir","par_how":"Comment lire les fiches","spec_h":"Où se placent les partis","pos_note":"Les positions sur l'axe gauche-droite viennent de l'enquête d'experts Chapel Hill (ou de l'enquête d'experts la plus proche quand elle ne couvre pas le pays). Les fiches sont classées par nombre de sièges. Le casier ne retient que les affaires avec un acte officiel (décision, mise en examen, sanction, exclusion), avec les mêmes plafonds pour tous les partis ; les proches et les non-membres en sont exclus. Le nombre d'affaires reflète en partie la taille d'un parti et ses années au pouvoir.",born_was:(o,r)=>`sous le nom ${o}${r?`, renommé en ${r}`:""}`});
Object.assign(T.fr,{ptag:{gap:"Contradiction",mixed:"À moitié",kept:"Tenu",consistent:"Cohérent",rights:"⚠ Alerte droits"},also_h:"À savoir aussi",pairs_note:"Un aperçu, pas un bilan complet : quelques promesses, face à ce qu'ils ont réellement fait sur le même sujet.",demo_ev:{eu2024:"européennes de juin 2024",odoxa2512:"sondage Odoxa, décembre 2025"},demo_as:n=>`(noté sous le nom ${n})`,demo_reg_t:e=>`de tous les inscrits l'ont choisi, abstentionnistes compris (${e}).`,demo_rej_t:e=>`prêts à voter pour un rival rien que pour lui barrer la route (${e}).`,demo_vp_t:y=>`Enquête d'experts V-Party (institut V-Dem), ${y}.`,demo_info:{"reg": "Ses voix divisées par l'ensemble des inscrits, et non par les seuls votes exprimés. Un parti peut arriver en tête et gagner beaucoup de sièges avec une minorité du corps électoral : ce chiffre montre combien de citoyens l'ont vraiment choisi, à comparer au bruit qu'il fait.", "rej": "La part des personnes prêtes à voter pour un rival rien que pour écarter ce parti. Un chiffre élevé signifie que le parti divise plus qu'il ne convainc, quel que soit son score.", "ap": "Dans quelle mesure le parti accepte les règles de la démocratie, selon des experts indépendants : élections libres et loyales, respect des adversaires, droits des minorités, rejet de la violence politique. 100 = pleinement pluraliste, 0 = pas du tout. Vert : rassurant ; rouge : alarmant.", "pol": "La fréquence à laquelle ses dirigeants attaquent personnellement leurs adversaires ou les présentent comme des ennemis plutôt que des concurrents. Cela divise la société en camps, fait passer tout compromis pour une trahison, nourrit la peur de l'autre et chasse du débat les faits et les solutions. Noté par des experts indépendants : 0 = jamais, 100 = toujours. Vert : rassurant ; rouge : alarmant."},demo_what:"Qu'est-ce que c'est",demo_ap_t:y=>`Enquête d'experts V-Party, ${y} : attachement aux règles démocratiques, respect des adversaires et des minorités, rejet de la violence politique (0 = pleinement pluraliste, 1 = pas du tout).`,demo_pol_t:y=>`V-Party, ${y} : fréquence des attaques personnelles et de la diabolisation des adversaires par ses dirigeants, moteur de polarisation et de peur de l'autre (0 = jamais, 100 = toujours).`,demo_h:"Baromètre démocratique",demo_na:"pas encore mesuré",demo_reg:"Poids réel",demo_rej:"Rejet",demo_ap:"Pluralisme",demo_pol:"Polarisation",demo_reg_na:"Part de tous les inscrits ayant voté pour lui : pas encore de résultat national comparable.",demo_rej_na:"Pas encore de sondage national comparable.",demo_vp_na:"Non couvert par l'enquête d'experts V-Party.",demo_note:"Mesuré par d'autres, jamais par nous : résultats officiels, sondage national et enquête d'experts V-Party de l'institut V-Dem (université de Göteborg). Un parti qui fait du bruit n'est pas forcément un grand parti : comparez son poids réel au vacarme.",nav_cmp:"Comparer",cmp_teaser:"Tous les pays côte à côte, continent par continent : espérance de vie, scolarité, homicides, liberté de la presse, libertés, corruption.",vote_eye:"Avant le prochain vote",vote_h:"Comment voter, en pratique",turnout_last:"Dernière participation :",t_fig:"Chiffres clés",t_watch:"À surveiller",axis_na:"Non placé sur l'axe gauche-droite",axis_na_country:"Aucun parti n'est placé ici sur l'axe gauche-droite : sans partis en concurrence ni vote libre, l'échelle n'a rien à mesurer. Voir chaque fiche.",credit_edge:"À son actif",kept0:"Tenue, effet en cours de vérification",pst:{kept:"Tenue, effet mesuré",token:"Tenue sur le papier",partial:"En partie",broken:"Rompue",untested:"Jamais testée"},effect:"effet mesuré",
 prom_note:"3 ou 4 promesses concrètes tirées de son dernier programme, chacune vérifiée sur un acte officiel ou un compteur indépendant. « Effet mesuré » exige une mesure indépendante de l'effet sur les gens ; une promesse adoptée sans effet mesurable, symbolique ou vite défaite compte « sur le papier » (un quart de point). « En partie » couvre aussi une promesse portée par le parti mais bloquée par d'autres. Une promesse qui exige un pouvoir que le parti n'a jamais eu ne peut pas être testée.",
 prom_count:(k,o,p,b,u)=>`${k} avec effet · ${o} sur le papier · ${p} en partie · ${b} rompue${b>1?"s":""} · ${u} jamais testée${u>1?"s":""}`,
 fl:"Extrême gauche",fr_:"Extrême droite",edge_note:"Bout de l'axe, selon les enquêtes d'experts",edge_h:"Avant de voter"});
Object.assign(T.es,{gb_h:"Barómetro del gobierno",gb_dem:"Democracia",gb_plur:"Pluralismo del poder",gb_app:"Popularidad",gb_trust:"Confianza en el gobierno",gb_prom:"Promesas cumplidas",gb_cpi:"Integridad (corrupción percibida)",gb_reg:["Autocracia cerrada","Autocracia electoral","Democracia electoral","Democracia liberal"],gb_own:(v,n)=>v==null?"":`Prometómetro de Barotico para ${n}: ${v}/100.`,gb_rank:r=>`puesto ${r}`,gb_na:"Aún no hay una cifra comparable.",gb_note:"Rojo: alarmante; verde: tranquilizador. Lo miden otros, nunca nosotros, salvo el prometómetro, que usa las fuentes de cada ficha de partido.",gb_info:{dem:"El índice de democracia liberal de V-Dem: elecciones libres y limpias, libertad de expresión y de asociación, justicia independiente, límites al poder ejecutivo. 100 = plenamente democrático. V-Dem clasifica además los países en cuatro regímenes: autocracia cerrada (sin elecciones reales, por ejemplo China o Corea del Norte), autocracia electoral (elecciones sin competencia limpia), democracia electoral y democracia liberal. Lo evalúan miles de expertos (instituto V-Dem, Universidad de Gotemburgo).",plur:"En qué medida el partido o los partidos en el poder aceptan las reglas de la democracia, según la encuesta de expertos V-Party: elecciones libres, respeto a los adversarios y a las minorías, rechazo de la violencia política. 100 = plenamente pluralista. Es la misma medida que en cada ficha de partido.",app:"La parte de personas que aprueban al jefe del ejecutivo o están satisfechas con él, en la última encuesta nacional reconocida. Verde desde el 55 %, amarillo del 40 al 54 %, naranja del 25 al 39 %, rojo por debajo del 25 %. En los países que V-Dem clasifica como autocracias la barra queda gris: allí las encuestas están demasiado condicionadas para leerse como tranquilizadoras o alarmantes.",trust:"La parte de personas que confían en el gobierno nacional, según una encuesta que compara países (encuesta de la OCDE sobre la confianza, Eurobarómetro). Misma escala de colores que la popularidad.",prom:"El prometómetro de Barotico aplicado a las promesas del partido en el poder: una promesa cumplida con un efecto medido cuenta entera, una cumplida en parte cuenta la mitad, una cumplida solo sobre el papel un cuarto. Se señalan los contadores independientes cuando existen.",cpi:"El índice de percepción de la corrupción de Transparency International: cuán corrupto juzgan expertos y empresarios al sector público. 100 = muy íntegro, 0 = muy corrupto."}});
Object.assign(T.es,{"b_h":"Adónde va el dinero público","b_lead":"Veinte años de gasto público, deuda y crecimiento, con los gobiernos de cada momento de fondo. El gasto abarca todas las administraciones públicas (Estado, entes locales, seguridad social), para poder comparar países.","b_info":"Fuente: Eurostat, según la clasificación internacional COFOG del gasto por función, para el conjunto de las administraciones públicas, en porcentaje del PIB. Un presupuesto aprobado un año suele heredarse del gobierno anterior, y las grandes crisis (2008, covid, energía) golpearon a casi todos los países a la vez: el gráfico muestra lo que cambió con cada gobierno, no quién fue el único responsable. La orientación (izquierda, centro, derecha) es la del partido que dirige el ejecutivo, como en las fichas de los partidos.","b_h1":"El gasto por función","b_unit":"en % del PIB","b_h2":"Lo que sube y lo que baja","b_h2s":"cada curva con su propia escala, en % del PIB","b_h3":"Deuda, déficit y crecimiento","b_mac":{"tot":"Gasto público total (% del PIB)","debt":"Deuda pública (% del PIB)","defc":"Déficit (–) o superávit (% del PIB)","gdp":"Crecimiento real del PIB (%)"},"b_cat":{"soc":"Protección social","hea":"Sanidad","edu":"Educación","eco":"Asuntos económicos","int":"Intereses de la deuda","def":"Defensa","sec":"Policía, justicia, seguridad","oth":"Administración, medio ambiente, vivienda, cultura"},"b_ori":{"l":"izquierda","c":"centro","r":"derecha","n":"sin partido"},"b_pres":"Bandas de fondo: quién dirigía el ejecutivo.","b_pm":"Primeros ministros:","b_src":"Fuente: Eurostat (octubre de 2026).","b_table":"Ver las cifras","b_year":"Año","b_total":"Total","crisis_fin":"Crisis de 2008","crisis_covid":"Covid",b_mini_h:"La economía de un vistazo",b_more:"Ver el gasto por función y los gobiernos",b_mob:"Consejo: estos gráficos se leen mejor en la pantalla de un ordenador.","crisis_energy":"Choque energético"});
Object.assign(T.es,{born_f:(y,o,r)=>`Fundado en ${y}${o?` (${o})`:""}${r?`, nombre actual desde ${r}`:""}`,born_age:n=>`${n} año${n>1?"s":""}`,born_tag:{young:"Partido joven: aún poco recorrido",old:"Partido con larga trayectoria"},born_gov:{never:"Nunca ha gobernado a nivel nacional",partner:"Ha participado en un gobierno nacional",lead:"Ha dirigido el gobierno nacional"},born_i:"Edad y experiencia de poder: no se juzga con el mismo historial a un partido de 3 años y a uno de 60. Un partido joven ha tenido poco tiempo para mostrar lo que hace; uno antiguo tiene un largo historial, para bien o para mal."});
Object.assign(T.es,{p_open:"Abrir la ficha completa",p_close:"Plegar la ficha"});
Object.assign(T.es,{"f_lead":"Dirección","f_seats":"Escaños","f_born":"Fundado en","f_gov":"En el poder","par_how":"Cómo leer las fichas","spec_h":"Dónde se sitúan los partidos","pos_note":"Las posiciones en el eje izquierda-derecha proceden de la encuesta de expertos Chapel Hill (o de la encuesta de expertos más cercana cuando no cubre el país). Las fichas se ordenan por número de escaños. El historial solo recoge casos con un acto oficial (sentencia, imputación, sanción, expulsión), con los mismos topes para todos los partidos; se excluye a familiares y no afiliados. El número de casos refleja en parte el tamaño del partido y sus años en el poder.",born_was:(o,r)=>`como ${o}${r?`, renombrado en ${r}`:""}`});
Object.assign(T.es,{ptag:{gap:"Contradicción",mixed:"A medias",kept:"Cumplido",consistent:"Coherente",rights:"⚠ Alerta de derechos"},also_h:"También conviene saber",pairs_note:"Un vistazo, no un balance completo: algunas promesas, frente a lo que realmente hicieron sobre el mismo tema.",demo_ev:{eu2024:"europeas de junio de 2024",odoxa2512:"encuesta Odoxa, diciembre de 2025"},demo_as:n=>`(evaluado como ${n})`,demo_reg_t:e=>`de todos los inscritos lo eligieron, abstencionistas incluidos (${e}).`,demo_rej_t:e=>`dispuestos a votar a un rival solo para cerrarle el paso (${e}).`,demo_vp_t:y=>`Encuesta de expertos V-Party (Instituto V-Dem), ${y}.`,demo_info:{"reg": "Sus votos divididos entre todos los inscritos, no solo entre los votos emitidos. Un partido puede ganar y obtener muchos escaños con una minoría del electorado: esta cifra muestra cuántos ciudadanos lo eligieron de verdad, frente al ruido que hace.", "rej": "La parte de personas dispuestas a votar a un rival solo para apartar a este partido. Una cifra alta significa que el partido divide más de lo que convence, sea cual sea su resultado.", "ap": "En qué medida el partido acepta las reglas de la democracia, según expertos independientes: elecciones libres y limpias, respeto a los adversarios, derechos de las minorías, rechazo de la violencia política. 100 = plenamente pluralista, 0 = en absoluto. Verde: tranquilizador; rojo: alarmante.", "pol": "Con qué frecuencia sus dirigentes atacan personalmente a sus adversarios o los presentan como enemigos y no como rivales. Divide la sociedad en bandos, hace pasar cualquier compromiso por traición, alimenta el miedo al otro y expulsa del debate los hechos y las soluciones. Evaluado por expertos independientes: 0 = nunca, 100 = siempre. Verde: tranquilizador; rojo: alarmante."},demo_what:"Qué es esto",demo_ap_t:y=>`Encuesta de expertos V-Party, ${y}: compromiso con las reglas democráticas, respeto a adversarios y minorías, rechazo de la violencia política (0 = plenamente pluralista, 1 = en absoluto).`,demo_pol_t:y=>`V-Party, ${y}: frecuencia de ataques personales y demonización de los adversarios por sus dirigentes, motor de polarización y miedo al otro (0 = nunca, 100 = siempre).`,demo_h:"Barómetro democrático",demo_na:"aún sin medir",demo_reg:"Peso real",demo_rej:"Rechazo",demo_ap:"Pluralismo",demo_pol:"Polarización",demo_reg_na:"Parte de todos los inscritos que lo votaron: aún sin resultado nacional comparable.",demo_rej_na:"Aún no hay una encuesta nacional comparable.",demo_vp_na:"No cubierto por la encuesta de expertos V-Party.",demo_note:"Medido por otros, nunca por nosotros: resultados oficiales, una encuesta nacional y la encuesta de expertos V-Party del Instituto V-Dem (Universidad de Gotemburgo). Un partido ruidoso no es necesariamente un partido grande: compare su peso real con el ruido.",nav_cmp:"Comparar",cmp_teaser:"Todos los países lado a lado, continente por continente: esperanza de vida, escolaridad, homicidios, libertad de prensa, libertades, corrupción.",vote_eye:"Antes de la próxima votación",vote_h:"Cómo votar, en la práctica",turnout_last:"Última participación:",t_fig:"Cifras clave",t_watch:"A vigilar",axis_na:"No situado en el eje izquierda-derecha",axis_na_country:"Ningún partido se sitúa aquí en el eje izquierda-derecha: sin partidos en competencia ni voto libre, la escala no tiene nada que medir. Ver cada ficha.",credit_edge:"En su haber",kept0:"Cumplida, efecto en verificación",pst:{kept:"Cumplida, efecto medido",token:"Cumplida sobre el papel",partial:"En parte",broken:"Incumplida",untested:"Nunca probada"},effect:"efecto medido",
 prom_note:"3 o 4 promesas concretas de su último programa, cada una comprobada con un acto oficial o un contador independiente. «Efecto medido» exige una medición independiente del efecto en la gente; una promesa aprobada sin efecto medible, simbólica o revertida pronto cuenta «sobre el papel» (un cuarto de punto). «En parte» incluye también una promesa que el partido impulsó pero otros bloquearon. Una promesa que exige un poder que el partido nunca tuvo no puede evaluarse.",
 prom_count:(k,o,p,b,u)=>`${k} con efecto · ${o} sobre el papel · ${p} en parte · ${b} incumplida${b>1?"s":""} · ${u} nunca probada${u>1?"s":""}`,
 fl:"Extrema izquierda",fr_:"Extrema derecha",edge_note:"Extremo del eje, según encuestas a expertos",edge_h:"Antes de votar"});
function isEdge(p){if(p.axis==="na")return false;return p.edge!=null?!!p.edge:(typeof p.pos==="number"&&p.style!=="rake"&&Math.abs(p.pos)>=1.5)}
const PSCLS={kept:"s-ok",token:"s-drop",partial:"s-run",broken:"s-rev",untested:"s-none"};
function verdictOf(k,p){const x=(typeof VERDICTS!=="undefined"&&VERDICTS[k]&&VERDICTS[k][p.id])||{};return{v:p.verdict||x.v,prom:p.prom||x.prom}}
function verdictBlock(k,p){
  const {v,prom}=verdictOf(k,p);if(!v&&!prom)return "";
  let meter="";
  if(prom&&prom.length){
    const n={kept:0,token:0,partial:0,broken:0,untested:0};prom.forEach(x=>n[x[1]]=(n[x[1]]||0)+1);
    const tested=n.kept+n.token+n.partial+n.broken,score=tested?(n.kept+n.partial*0.5+n.token*0.25)/tested:null;
    const [bh,bp]=score===null?t("untested_all"):t("bands")[score<0.25?0:score<0.5?1:score<0.75?2:3];
    const seg=["kept","token","partial","broken","untested"].filter(s=>n[s]).map(s=>`<i class="ps-${s}" style="flex:${n[s]}"></i>`).join("");
    meter=`<div class="pmeter"><div class="pm-head"><b>${t("prom_h")}</b><span class="pm-band">${bh}</span></div>
      <div class="pm-bar" role="img" aria-label="${T[lang].prom_count(n.kept,n.token,n.partial,n.broken,n.untested)}">${seg}</div>
      <p class="pm-count mono">${T[lang].prom_count(n.kept,n.token,n.partial,n.broken,n.untested).split(" · ").map(x=>`<span>${x}</span>`).join("")}</p><p class="explain">${bp}</p>
      <details><summary>${t("prom_detail")}</summary><ul class="casier promlist">${prom.map(([x,s,u,e])=>`<li><span class="stamp ${PSCLS[s]}">${s==="kept"&&!e?t("kept0"):t("pst")[s]}</span> <span class="ptxt">${esc(tr(x))}${u?` <a href="${u}" target="_blank" rel="noopener" class="src-a">${t("source")}</a>`:""}${s==="kept"&&e?` · <a href="${e}" target="_blank" rel="noopener" class="src-a">${t("effect")}</a>`:""}</span></li>`).join("")}</ul><p class="sources">${t("prom_note")}</p></details></div>`;
  }
  const ed=isEdge(p);
  return `<div class="verdict${ed?" edge":""}"><p class="eyebrow">${t("verdict_h")}${ed?` · <span class="edge-tag">${p.pos<0?t("fl"):t("fr_")}</span>`:""}</p>${meter}${v?`<blockquote class="chute">${tr(v).split(/\n\n+/).map(x=>`<p>${esc(x)}</p>`).join("")}</blockquote>`:""}</div>`;
}

