function figure(pos,style){
  const x=80+pos*26, ang=style==="rake"?0:pos*6, side=pos<-0.35?-1:pos>0.35?1:0;
  let arms;
  if(style==="rake") arms=`<path d="M0 -56 L-30 -68"/><path d="M0 -56 L30 -68"/><circle cx="-31" cy="-69" r="3.5"/><circle cx="31" cy="-69" r="3.5"/><path d="M-31 -69 v34 M-38 -36 h14" stroke-width="2"/><path d="M31 -69 v34 M24 -36 h14" stroke-width="2"/>`;
  else if(side===0) arms=`<path d="M0 -56 L-15 -36"/><path d="M0 -56 L15 -36"/><circle cx="-16" cy="-35" r="3.5"/><circle cx="16" cy="-35" r="3.5"/>`;
  else {const s=side;arms=`<path d="M0 -56 L${28*s} -60"/><path d="M0 -54 L${26*s} -48"/><circle cx="${30*s}" cy="-61" r="3.5"/><circle cx="${28*s}" cy="-47" r="3.5"/>`}
  return `<svg class="fig" viewBox="-20 0 200 124" role="img" aria-label="${T[lang].fig_aria(side<0?t("fig_l"):side>0?t("fig_r"):t("fig_c"))}">
   <line x1="12" y1="108" x2="148" y2="108" stroke="var(--line)" stroke-width="2"/>
   <line x1="80" y1="102" x2="80" y2="114" stroke="var(--muted)" stroke-width="1"/>
   <text x="12" y="122" font-size="9" fill="var(--muted)" font-family="IBM Plex Mono, monospace">${t("left").toUpperCase()}</text>
   <text x="148" y="122" font-size="9" fill="var(--muted)" text-anchor="end" font-family="IBM Plex Mono, monospace">${t("right").toUpperCase()}</text>
   <g transform="translate(${x} 108) rotate(${ang})" stroke="var(--ink)" stroke-width="3" stroke-linecap="round" fill="var(--ink)">
    <path d="M0 -30 L-8 0 M0 -30 L8 0" fill="none"/><path d="M0 -30 L0 -62" fill="none"/>
    <g>${arms}</g>
    <circle cx="0" cy="-75" r="11" fill="var(--surface)"/>
    <circle cx="${side*3-3}" cy="-77" r="1.4" stroke="none"/><circle cx="${side*3+3}" cy="-77" r="1.4" stroke="none"/>
   </g></svg>`;
}
