function bindMirror(){
  const chips=[...document.querySelectorAll(".chip")];
  const update=()=>{
    chips.forEach(b=>{const on=picked.has(+b.dataset.i);b.setAttribute("aria-pressed",on);b.disabled=!on&&picked.size>=MAX});
    document.getElementById("cnt").textContent=`${picked.size} / ${MAX} ${t("chosen")}`;
    const sel=[...picked].map(i=>VALUES[i]);
    const needle=document.getElementById("needle"),verdict=document.getElementById("verdict"),explain=document.getElementById("explain");
    if(sel.length<3){needle.style.left="50%";verdict.textContent=t("pick3");explain.textContent=t("neutral_hint");return}
    const avg=sel.reduce((s,[,w])=>s+w,0)/sel.length;
    needle.style.left=(50+avg/2*46)+"%";
    verdict.textContent=avg<=-1.2?t("v_l2"):avg<-0.4?t("v_l1"):avg<0.4?t("v_c"):avg<1.2?t("v_r1"):t("v_r2");
    const nm=([v])=>tr(v),Lv=sel.filter(([,w])=>w<0).map(nm),Rv=sel.filter(([,w])=>w>0).map(nm),Nv=sel.filter(([,w])=>w===0).map(nm);
    const parts=[];
    if(Lv.length)parts.push(`${Lv.join(", ")}: ${t("by_left")}`);
    if(Rv.length)parts.push(`${Rv.join(", ")}: ${t("by_right")}`);
    if(Nv.length)parts.push(`${Nv.join(", ")}: ${t("by_all")}`);
    parts.push(t("next_step"));
    explain.textContent=parts.join(" ");
  };
  chips.forEach(b=>b.addEventListener("click",()=>{const i=+b.dataset.i;picked.has(i)?picked.delete(i):picked.size<MAX&&picked.add(i);update()}));
  document.getElementById("reset").addEventListener("click",()=>{picked.clear();update()});
  update();
}
function selectTab(id){document.querySelectorAll(".tab").forEach(x=>{const on=x.id===id;x.setAttribute("aria-selected",on);document.getElementById(x.getAttribute("aria-controls")).hidden=!on})}
function bindTabs(){document.querySelectorAll(".tab").forEach(x=>x.addEventListener("click",()=>selectTab(x.id)))}
function bindShare(){
  document.querySelectorAll("[data-share]").forEach(b=>b.addEventListener("click",()=>{
    const [ck,id]=b.dataset.share.split("-"),txt=shareText(ck,id);
    const done=()=>{b.textContent=t("copied");setTimeout(()=>b.textContent=t("copy"),2000)};
    const fallback=()=>{const ta=document.createElement("textarea");ta.value=txt;ta.className="copybox";b.closest(".pcard").appendChild(ta);ta.focus();ta.select();b.textContent=t("select_copy")};
    try{navigator.clipboard.writeText(txt).then(done,fallback)}catch(e){fallback()}
  }));
}
function chrome(){
  document.documentElement.lang=lang;
  document.querySelectorAll("[data-t]").forEach(el=>{const v=t(el.dataset.t);if(typeof v==="string")el.textContent=v});
  const opts=[["en","English"]];
  if(browserLang!=="en")opts.push(["browser",LANGS.includes(browserLang)?langName(browserLang):T.en.browser_tr(langName(browserLang))]);
  if(PATHMODE){opts.length=0;opts.push(["en","English"]);if(browserLang!=="en"&&LANGS.includes(browserLang))opts.push([browserLang,langName(browserLang)]);else if(browserLang!=="en")opts.push(["browser",T.en.browser_tr(langName(browserLang))]);if(lang!=="en"&&!opts.some(o=>o[0]===lang))opts.push([lang,langName(lang)])}
  const sw=LANGS.map(L=>{const cur=L===lang;return `<a class="lsw${cur?" on":""}" href="${PATHMODE?pathFor(curRaw(),L):"#"}" data-lang="${L}" hreflang="${L}" lang="${L}" title="${LANG_NAMES[L]}" aria-label="${LANG_NAMES[L]}"${cur?' aria-current="true"':""}>${L.toUpperCase()}</a>`}).join("");
  ["lang-sw","lang-sw-d","lang-sw-m"].forEach(id=>{const e=document.getElementById(id);if(e)e.innerHTML=sw});
  ["lang-select","lang-select-m"].forEach(id=>{const s=document.getElementById(id);if(!s)return;s.innerHTML=opts.map(([v,n])=>`<option value="${v}">${esc(n)}</option>`).join("");s.value=PATHMODE?(lang==="en"&&useBrowser&&opts.some(o=>o[0]==="browser")?"browser":lang):useBrowser?"browser":"en";s.hidden=opts.length<2});
  document.getElementById("dd-pays").innerHTML=countriesMenu(false);document.getElementById("sheet-pays").innerHTML=countriesMenu(true);
  const ll=document.getElementById("legal-links");if(ll)ll.innerHTML=[["mentions",LEG.sections[0][1]],["charter",LEG.charterLink],["corrections",LEG.report],["privacy",LEG.sections[3][1]],["ai",LEG.sections[4][1]]].map(([id,l])=>`<a href="#legal-${id}">${esc(tr(l))}</a>`).join(" · ");
  const bm=document.getElementById("bmc");
  if(BMC_URL){bm.href=BMC_URL;bm.removeAttribute("aria-disabled");document.getElementById("bmc-note").hidden=true}
  else{bm.removeAttribute("href");bm.setAttribute("aria-disabled","true");const n=document.getElementById("bmc-note");n.hidden=false;n.textContent=t("sup_soon")}
  const bn=document.getElementById("langbanner");
  if(autoLang&&useBrowser){bn.hidden=false;document.getElementById("lb-text").textContent=LANGS.includes(browserLang)?T[lang].banner(lang):T.en.lang_other((()=>{try{return new Intl.DisplayNames(["en"],{type:"language"}).of(browserLang)}catch(e){return langName(browserLang)}})());document.getElementById("lb-en").textContent=t("to_en");document.getElementById("lb-en").hidden=lang==="en";document.getElementById("lb-ok").textContent=t("ok")}else bn.hidden=true;
}
function mediaPage(){
  const m=MT[lang]||MT.en,nm=x=>esc(tr(x));
  const groups=["europe","americas","africa","asia","oceania"].map(ct=>{const ks=readyKeys().filter(k=>contOf(k)===ct);if(!ks.length)return "";return `<div class="continent"><p class="eyebrow">${t(ct)}</p><div class="clist">${ks.map(k=>`<a class="ccard" href="#${k}-medias"><span>${esc(tr(info(k).name))}</span><span class="mono">${t("t_med")} →</span></a>`).join("")}</div></div>`}).join("");
  return `<div class="chead" style="grid-template-columns:minmax(0,1fr)"><div><p class="eyebrow">${m.eye}</p><h1>${m.h}</h1><p class="lead" style="margin-top:10px">${nm(MEDIA.intro)}</p></div></div>
   <aside class="disc"><b>${nm(MEDIA.how.h)}</b>${MEDIA.how.items.map(x=>`<p>${nm(x)}</p>`).join("")}<p class="sources"><a href="${MEDIA.how.src}" target="_blank" rel="noopener">${MEDIA.how.srcName}</a></p></aside>
   <section><p class="lead">${t("med_pick")}</p>${groups}</section>`;
}
let firstRender=true;
function render(){renderView();pathLinks();if(PATHMODE&&!firstRender){const raw=curRaw(),k=raw.split("-")[0],c=isReady(k)&&(C[k]||REG.meta[k]);document.title=c?`${tr(c.name)} · Barotico`:"Barotico"}firstRender=false}
function renderView(){
  if(PATHMODE&&/^\/(en\/?)?$/.test(location.pathname)&&location.hash.length>1){const r=curRaw(),k=r.split("-")[0];if(isReady(k)||PAGE_SLUG[k]){history.replaceState(null,"",pathFor(r));}}
  chrome();
  const raw=curRaw();
  const [r,party]=raw.split("-");
  let key=r==="medias"?"medias":r==="apropos"?"apropos":r==="legal"?"legal":r==="comparer"?"comparer":isReady(r)?r:"accueil";
  const view=document.getElementById("view");
  if(key!=="accueil"&&key!=="medias"&&key!=="apropos"&&key!=="legal"&&key!=="comparer"&&!C[key]){
    if(REG.full[key])ingest(key);
    else{view.innerHTML=`<p class="pending" style="padding:48px 0">${t("loading")}</p>`;loadCountry(key);return}
  }
  view.innerHTML=key==="comparer"?comparePage():key==="medias"?mediaPage():key==="apropos"?aboutPage():key==="legal"?legalPage():key==="accueil"?landing():countryPage(key);
  const cur=r==="voter"?"voter":(C[key]?"pays":key);
  document.querySelectorAll(".navlink").forEach(a=>{if(a.dataset.r===cur)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current")});
  closeDD();
  if(key==="comparer"){bindFilter();window.scrollTo(0,0);return}
  if(key==="medias"||key==="apropos"||key==="legal"){const tg=key==="legal"&&party&&document.getElementById(party);if(tg)tg.scrollIntoView({block:"start"});else window.scrollTo(0,0);return}
  if(key==="accueil"){
    bindMirror();bindFilter();bindGuide();bindExample();
    document.querySelectorAll("[data-jump]").forEach(a=>a.addEventListener("click",e=>{e.preventDefault();document.getElementById(a.dataset.jump).scrollIntoView({behavior:"smooth"})}));
    const tgt=["voter","pays","soutien","comparatif","guide","exemple","miroir","actu"].includes(r)&&document.getElementById(r);
    if(tgt)tgt.scrollIntoView({block:"start"});else window.scrollTo(0,0);
    return;
  }
  bindTabs();bindShare();
  document.querySelectorAll(".cg-tab").forEach(x=>x.addEventListener("click",()=>{selectTab(x.dataset.tab);const tb=document.querySelector(".tabs");if(tb)tb.scrollIntoView({block:"start",behavior:"smooth"})}));
  if(party==="medias"){selectTab("t-med");window.scrollTo(0,0);return}
  if(party==="figures"){selectTab("t-fig");window.scrollTo(0,0);return}
  if(party==="budget"){selectTab("t-gov");const bb=document.querySelector("#p-gov .budget");if(bb)bb.scrollIntoView({block:"start"});else window.scrollTo(0,0);return}
  if(party==="watch"){selectTab("t-watch");window.scrollTo(0,0);return}
  if(party==="partis"){selectTab("t-par");bindToggles();const pp=document.getElementById("p-par");if(pp)pp.scrollIntoView({block:"start"});return}
  bindToggles();
  const target=party&&document.getElementById("party-"+party);
  if(target){selectTab("t-par");openCard(target,true);target.scrollIntoView({block:"start"})}else window.scrollTo(0,0);
}
function setLang(v){if(LANGS.includes(v)&&!PATHMODE){lang=v;useBrowser=v!=="en";autoLang=false;store("barotico-lang",v);picked=new Set(picked);render();return}if(PATHMODE){const L=v==="browser"?browserLang:v;store("barotico-lang",LANGS.includes(L)?L:"en");location.assign(pathFor(curRaw(),LANGS.includes(L)?L:"en")+(L==="en"?"?nolang":""));return}useBrowser=v==="browser";lang=useBrowser&&LANGS.includes(browserLang)?browserLang:"en";autoLang=useBrowser&&!LANGS.includes(browserLang);store("barotico-lang",v);picked=new Set(picked);render()}
["lang-select","lang-select-m"].forEach(id=>{const e=document.getElementById(id);if(e)e.addEventListener("change",ev=>setLang(ev.target.value))});
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("a[data-lang]");if(!a)return;e.preventDefault();e.stopPropagation();const L=a.dataset.lang;if(L===lang)return;setLang(L)},true);
(function menu(){
  const sheet=document.getElementById("sheet"),btn=document.getElementById("menubtn");
  const open=()=>{sheet.hidden=false;btn.setAttribute("aria-expanded","true");sheet.querySelector(".sheet-x").focus()};
  const close=()=>{sheet.hidden=true;btn.setAttribute("aria-expanded","false")};
  btn.addEventListener("click",open);
  sheet.querySelectorAll("[data-close]").forEach(el=>el.addEventListener("click",close));
  sheet.addEventListener("click",e=>{if(e.target.closest("a"))close()});
  const ddb=document.getElementById("dd-btn"),ddp=document.getElementById("dd-pays");
  ddb.addEventListener("click",e=>{e.stopPropagation();const o=ddb.getAttribute("aria-expanded")==="true";ddb.setAttribute("aria-expanded",!o);ddp.hidden=o});
  ddp.addEventListener("click",e=>{if(e.target.closest("a"))closeDD()});
  document.addEventListener("click",e=>{if(!e.target.closest(".dd"))closeDD()});
  document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(!sheet.hidden)close();if(!ddp.hidden){closeDD();ddb.focus()}}});
  const top=document.getElementById("top");let last=window.scrollY;
  window.addEventListener("scroll",()=>{const y=window.scrollY;if(window.innerWidth<=820&&y>80&&y>last+4)top.classList.add("hide");else if(y<last-4||y<=80)top.classList.remove("hide");last=y},{passive:true});
})();
document.getElementById("lb-en").addEventListener("click",()=>setLang("en"));
document.getElementById("lb-ok").addEventListener("click",()=>{autoLang=false;store("barotico-lang",PATHMODE?lang:(useBrowser?(LANGS.includes(lang)?lang:"browser"):"en"));document.getElementById("langbanner").hidden=true});
if(PATHMODE){
  document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("a[href]");if(!a||e.defaultPrevented||e.button||e.metaKey||e.ctrlKey||e.shiftKey||a.target==="_blank")return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||!/^\/(en|fr|es)\//.test(u.pathname))return;e.preventDefault();if(u.pathname===location.pathname&&u.hash){history.pushState(null,"",u.pathname+u.hash);render();return}history.pushState(null,"",u.pathname+u.hash);render()});
  window.addEventListener("popstate",render);window.addEventListener("hashchange",render);
}else window.addEventListener("hashchange",render);
render();
